            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            r0, r1 = min(x for x,y in cells), max(x for x,y in cells)
            c0, c1 = min(y for x,y in cells), max(y for x,y in cells)
            top = {cc for rr,cc in cells if rr == r0}
            gaps = [cc for cc in range(c0+1,c1) if cc not in top]
            if not gaps:
                continue
            gap = gaps[0]
            left_run = 0
            cc = gap-1
            while cc in top:
                left_run += 1
                cc -= 1
            right_run = 0
            cc = gap+1
            while cc in top:
